 const caps=['payrun-net.view','payrun-net.edit','payruns.view','payruns.edit','work-pay.view','payroll-accruals.view','payroll-accruals.edit','payroll-adjustments.view','payroll-adjustments.edit','accounts.view','journals.view','journals.edit'];
