test('actual107to108 preserves recorded project salary and bonus and starts with no run or claims',async()=>{
 const f=await fixture({throughSchema:107});try{const snapshot=async()=>{const out:Record<string,unknown>={};for(const t of ['finance_journals','finance_journal_lines','payroll_project_accruals','payroll_salary_accruals','payroll_adjustments','work_engagement_revisions'])out[t]=(await f.pg.query('SELECT to_jsonb(x) x FROM public.'+t+' x ORDER BY to_jsonb(x)::text')).rows;return out;};const before=await snapshot();await f.pg.exec(await readFile(new URL('../db/migrations/108_payrun_groups.sql',import.meta.url),'utf8'));assert.deepEqual(await snapshot(),before);assert.equal((await f.pg.query('SELECT public.schema_revision() n')).rows[0].n,108);assert.equal((await f.pg.query('SELECT * FROM public.payrun_groups')).rows.length,0);assert.equal((await made(f)).grossAmount,'3350.25');}finally{await f.pg.close();}
});
